files.after:
.ui_themePreview {
  display: block;
}

.ui_themePreview > .ant-tree .ant-tree-node-content-wrapper {
  color: var(--ui-theme-preview-color, #334155);
  padding: var(--ui-theme-preview-node-padding, 8px 12px);
  border-radius: var(--ui-theme-preview-node-radius, 6px);
}

.ui_themePreview > .ant-tree .ant-tree-node-content-wrapper:hover {
  background: var(--ui-theme-preview-color, #334155);
  padding: var(--ui-theme-preview-node-padding, 8px 12px);
  border-radius: var(--ui-theme-preview-node-radius, 6px);
}
